-- Fakt kartochkalarining ruscha matni — 9-partiya: To'maris, Shiroq, Spitamen.
--
-- MUHIM. Asl matndagi «Rivoyatga ko'ra» ehtiyotkorligi tarjimada ham
-- saqlangan: «Согласно преданию». Bu metodist qo'ygan chegara — afsona
-- hujjatlashtirilgan fakt sifatida ko'rsatilmaydi.

-- ===== To'maris =====
UPDATE fact_cards SET topic_ru = 'Кто я?', question_ru = 'Царицей какого народа была Томирис?', fact_ru = 'Я Томирис — царица древнего народа массагетов, жила в VI веке до нашей эры на земле Турана.' WHERE id = 473;
UPDATE fact_cards SET topic_ru = 'Мой народ', question_ru = 'Где жили массагеты?', fact_ru = 'Мой народ — массагеты — был свободным кочевым народом, жившим по берегам Амударьи и в песках Кызылкума.' WHERE id = 474;
UPDATE fact_cards SET topic_ru = 'Как я стала царицей', question_ru = 'При каких обстоятельствах Томирис начала править своим народом?', fact_ru = 'Согласно преданию, после смерти моего супруга я сама возглавила свой народ.' WHERE id = 475;
UPDATE fact_cards SET topic_ru = 'Нашествие Кира II', question_ru = 'Когда Кир II пошёл войной на массагетов?', fact_ru = 'В 530 году до нашей эры персидский царь Кир II с огромным войском двинулся на массагетов.' WHERE id = 476;
UPDATE fact_cards SET topic_ru = 'Моё предложение мира', question_ru = 'Какое предложение Томирис сделала Киру II?', fact_ru = 'Согласно преданию, я предложила Киру II вернуться назад без войны, с миром, но царь отверг это предложение.' WHERE id = 477;
UPDATE fact_cards SET topic_ru = 'Свидетельство Геродота', question_ru = 'Кто записал события, связанные с Томирис?', fact_ru = 'События, связанные со мной, записал древнегреческий историк Геродот, которого называют «отцом истории».' WHERE id = 478;
UPDATE fact_cards SET topic_ru = 'Великая битва', question_ru = 'Как Геродот описал битву с массагетами?', fact_ru = 'Геродот назвал эту битву «страшнее всех прочих сражений» — в долгом бою верх взял мой народ.' WHERE id = 479;
UPDATE fact_cards SET topic_ru = 'Исход нашествия', question_ru = 'Чем закончилась судьба Кира II?', fact_ru = 'Царь-завоеватель Кир II погиб на том поле битвы.' WHERE id = 480;
UPDATE fact_cards SET topic_ru = 'Память обо мне', question_ru = 'Символом чего сегодня стало имя Томирис?', fact_ru = 'Сегодня моё имя стало символом защиты Родины и мужества.' WHERE id = 481;
UPDATE fact_cards SET topic_ru = 'Держава Кира II', question_ru = 'Основателем какого государства был Кир II, пошедший войной на Томирис?', fact_ru = 'Кир II, положивший глаз на мою землю, был основателем государства Ахеменидов. Он подчинил Мидию, Лидию и Вавилон и создал огромную державу.' WHERE id = 1800;
UPDATE fact_cards SET topic_ru = 'Наше оружие', question_ru = 'Из какого металла народ Томирис — массагеты — изготавливал своё оружие?', fact_ru = 'Как пишет Геродот, мой народ делал оружие из бронзы, а украшения — из золота. Массагетские всадники сражались копьём, луком и секирой.' WHERE id = 1801;
UPDATE fact_cards SET topic_ru = 'Женщины моего народа', question_ru = 'Каким было место женщины в обществе народа Томирис?', fact_ru = 'У массагетов женщины наравне с мужчинами умели ездить верхом и сражаться. Потому мой народ смело поддержал меня — женщину-правительницу.' WHERE id = 1802;
UPDATE fact_cards SET topic_ru = 'Мой сын Спаргапис', question_ru = 'Кто был сыном Томирис, возглавлявшим часть войска?', fact_ru = 'Как пишет Геродот, мой сын Спаргапис возглавлял часть моего войска. Персы одолели его не в открытом бою, а хитростью.' WHERE id = 1803;
UPDATE fact_cards SET topic_ru = 'Почитание солнца', question_ru = 'Что народ Томирис — массагеты — считал священным?', fact_ru = 'Как пишет Геродот, мой народ считал солнце священным и посвящал ему самых быстрых своих коней.' WHERE id = 1804;
UPDATE fact_cards SET topic_ru = 'Первая женщина-правительница', question_ru = 'Каким правителем признана Томирис в нашей истории?', fact_ru = 'Я — одна из первых женщин-правительниц и полководцев, чьё имя сохранилось в истории нашей страны.' WHERE id = 1805;
UPDATE fact_cards SET topic_ru = 'Моё имя сегодня', question_ru = 'В каком значении сегодня дают имя Томирис?', fact_ru = 'Сегодня в Узбекистане многим девочкам дают имя Томирис. Для родителей это имя — знак отваги и любви к Родине.' WHERE id = 1806;

-- ===== Shiroq =====
UPDATE fact_cards SET topic_ru = 'Кто я?', question_ru = 'Из какого племени вышел Ширак и кем он был?', fact_ru = 'Я Ширак — простой пастух из племени саков.' WHERE id = 482;
UPDATE fact_cards SET topic_ru = 'Мой народ — саки', question_ru = 'Как саки описаны в Бехистунских надписях?', fact_ru = 'Мой народ был отважными скотоводами; в Бехистунской наскальной надписи саки описаны как народ, «носящий островерхие шапки».' WHERE id = 483;
UPDATE fact_cards SET topic_ru = 'Поход Дария I', question_ru = 'Какой персидский царь двинул войско на землю саков?', fact_ru = 'Персидский царь Дарий I на третий год своего правления двинул войско на землю саков.' WHERE id = 484;
UPDATE fact_cards SET topic_ru = 'Мой замысел', question_ru = 'В каком облике Ширак явился к персам?', fact_ru = 'Согласно преданию, я явился к персам под видом проводника и пообещал вывести их в тыл сакам.' WHERE id = 485;
UPDATE fact_cards SET topic_ru = 'Путь в пустыню', question_ru = 'Куда Ширак завёл вражеское войско?', fact_ru = 'Согласно преданию, я завёл вражеское войско известной лишь мне тропой в безводную пустыню.' WHERE id = 486;
UPDATE fact_cards SET topic_ru = 'Семь дней пути', question_ru = 'Сколько дней персы шли по пустыне?', fact_ru = 'Согласно преданию, мы шли по безводной пустыне семь дней — и только тогда персы поняли, что обмануты.' WHERE id = 487;
UPDATE fact_cards SET topic_ru = 'Самопожертвование', question_ru = 'Что Ширак сделал ради своей Родины?', fact_ru = 'Я отдал свою жизнь за свободу Родины.' WHERE id = 488;
UPDATE fact_cards SET topic_ru = 'Итог', question_ru = 'К какому итогу привела отвага Ширака?', fact_ru = 'Благодаря моей отваге поход Дария I на саков окончился неудачей.' WHERE id = 489;
UPDATE fact_cards SET topic_ru = 'Источник предания', question_ru = 'Кто записал предание о Шираке?', fact_ru = 'Предание обо мне записал живший во II веке нашей эры историк Полиэн, опиравшийся на сакские сказания.' WHERE id = 490;
UPDATE fact_cards SET topic_ru = 'Держава Ахеменидов', question_ru = 'Правителем какой державы был Дарий I, против которого выступил Ширак?', fact_ru = 'Дарий I, приведший войско на мою землю, был царём державы Ахеменидов. В то время это государство простиралось от Египта до реки Инд.' WHERE id = 1779;
UPDATE fact_cards SET topic_ru = 'Сакские роды', question_ru = 'Какие роды сакского народа, к которому принадлежал Ширак, известны в истории?', fact_ru = 'Мой народ делился на несколько родов: в истории отмечены саки-тиграхауда в островерхих шапках, саки-хаумаварга и саки, жившие за рекой.' WHERE id = 1780;
UPDATE fact_cards SET topic_ru = 'Наши земли', question_ru = 'На каких землях жил народ Ширака — саки?', fact_ru = 'Саки жили по берегам Сырдарьи, вокруг Аральского моря и в широких степях у подножий гор.' WHERE id = 1781;
UPDATE fact_cards SET topic_ru = 'Искусство верховой езды', question_ru = 'Какими воинами прославился народ Ширака — саки?', fact_ru = 'Мой народ учился ездить верхом с детства. Саки прославились как искусные всадники и меткие лучники.' WHERE id = 1782;
UPDATE fact_cards SET topic_ru = 'Записи Геродота', question_ru = 'Какой ещё древнегреческий историк оставил сведения о народе Ширака — саках?', fact_ru = 'О саках писал и древнегреческий историк Геродот: он описывал мой народ как храбрый и воинственный.' WHERE id = 1783;
UPDATE fact_cards SET topic_ru = 'Моё место в учебниках', question_ru = 'Где сегодня изучают предание об отваге Ширака?', fact_ru = 'Сегодня предание о моей отваге изучают в учебниках истории школ Узбекистана.' WHERE id = 1784;
UPDATE fact_cards SET topic_ru = 'Память обо мне', question_ru = 'Символом чего сегодня вспоминают имя Ширака?', fact_ru = 'Прошли тысячи лет, а имя моё не забылось. Имя Ширака стало на нашей земле символом верности Родине и самоотверженности.' WHERE id = 1785;

-- ===== Spitamen =====
UPDATE fact_cards SET topic_ru = 'Кто я?', question_ru = 'Кем был Спитамен?', fact_ru = 'Я Спитамен — одарённый организатор и военный предводитель Согдианы; в источниках моё имя встречается и в форме Спитаман.' WHERE id = 501;
UPDATE fact_cards SET topic_ru = 'Нашествие Александра', question_ru = 'Когда Александр Македонский вторгся в Мавераннахр?', fact_ru = 'В 329 году до нашей эры войска Александра Македонского перешли Амударью и вторглись в Мавераннахр.' WHERE id = 502;
UPDATE fact_cards SET topic_ru = 'Мараканда', question_ru = 'Какой город сейчас на месте занятой греко-македонскими войсками Мараканды?', fact_ru = 'В том же году греко-македонские войска заняли Мараканду — нынешний Самарканд.' WHERE id = 503;
UPDATE fact_cards SET topic_ru = 'Объединение народов', question_ru = 'Какие народы объединил Спитамен в восстании?', fact_ru = 'В восстании против завоевателей я объединил согдийцев, бактрийцев и саков.' WHERE id = 504;
UPDATE fact_cards SET topic_ru = 'Осада', question_ru = 'Какой город осаждал Спитамен?', fact_ru = 'Собрав немалое войско, я осадил Мараканду, находившуюся в руках врага.' WHERE id = 505;
UPDATE fact_cards SET topic_ru = 'Битва при Политимете', question_ru = 'Какую победу одержал Спитамен на Политимете?', fact_ru = 'На Политимете — нынешней реке Зеравшан — я устроил засаду и разбил присланный Александром на помощь отряд почти в три тысячи воинов.' WHERE id = 506;
UPDATE fact_cards SET topic_ru = 'Трёхлетняя борьба', question_ru = 'Сколько лет продолжалось сопротивление под началом Спитамена?', fact_ru = 'Под моим началом мой народ три года оказывал завоевателям упорное сопротивление.' WHERE id = 507;
UPDATE fact_cards SET topic_ru = 'Мой отказ от мира', question_ru = 'Как Спитамен ответил на предложение Александра о мире?', fact_ru = 'Александр предложил мне мир, но я отказался отдать свою Родину врагу.' WHERE id = 508;
UPDATE fact_cards SET topic_ru = 'Последняя битва', question_ru = 'Когда и как погиб Спитамен?', fact_ru = 'Осенью 328 года до нашей эры, после решающей битвы с неравными силами, я отступил в пустыню и там погиб от рук изменников.' WHERE id = 509;
UPDATE fact_cards SET topic_ru = 'Моя дочь Апама', question_ru = 'За кого вышла замуж дочь Спитамена?', fact_ru = 'Моя дочь Апама вышла замуж за греческого полководца Селевка — от них родился царь Антиох I.' WHERE id = 510;
UPDATE fact_cards SET topic_ru = 'История Бесса', question_ru = 'Какого сановника, изменившего своему царю, Спитамен схватил в 329 году до нашей эры и передал Александру?', fact_ru = 'Сначала мы с соратниками схватили Бесса, изменившего своему царю Дарию III, и передали его посланному Александром военачальнику. Это было в 329 году до нашей эры.' WHERE id = 1786;
UPDATE fact_cards SET topic_ru = 'Мой способ войны', question_ru = 'Какой способ ведения войны применял Спитамен против войск Александра?', fact_ru = 'Вместо открытого боя я применял внезапные удары и быстрый отход. Хорошее знание степных и пустынных дорог давало мне большое преимущество.' WHERE id = 1787;
UPDATE fact_cards SET topic_ru = 'Крайняя Александрия', question_ru = 'Какой город основал Александр на Сырдарье в годы борьбы Спитамена?', fact_ru = 'В 329 году до нашей эры, когда шла борьба со мной, Александр основал на Сырдарье город Александрию Эсхату — «Крайнюю Александрию».' WHERE id = 1788;
UPDATE fact_cards SET topic_ru = 'Свидетельства историков', question_ru = 'Какие древние историки написали о борьбе Спитамена?', fact_ru = 'О моей борьбе написали греческий историк Арриан в труде «Поход Александра» и римский историк Квинт Курций Руф в своей книге.' WHERE id = 1789;
UPDATE fact_cards SET topic_ru = 'Города Апамеи', question_ru = 'Что было названо в честь Апамы, дочери Спитамена?', fact_ru = 'В честь моей дочери Апамы на Востоке позже назвали несколько городов — Апамеями. А её сын Антиох стал правителем большой державы.' WHERE id = 1790;
UPDATE fact_cards SET topic_ru = 'Моя земля Согдиана', question_ru = 'Где располагалась Согдиана — родина Спитамена?', fact_ru = 'Моя родина Согдиана располагалась между Амударьёй и Сырдарьёй, а её сердцем были долины Зеравшана и Кашкадарьи.' WHERE id = 1791;
UPDATE fact_cards SET topic_ru = 'Память обо мне', question_ru = 'Символом чего сегодня вспоминают имя Спитамена?', fact_ru = 'Моё имя осталось в истории символом борьбы за свободу Родины. Сегодня в школах Узбекистана дети изучают историю моей борьбы.' WHERE id = 1792;
